import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication with optimized tile size and loop unrolling
matmul_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Calculate row and column of C element to compute
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    // Loop over tiles with unrolling
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load data into shared memory
        int tiledCol = t * TILE_SIZE + tx;
        int tiledRow = t * TILE_SIZE + ty;

        // Load A tile
        if (row < N && tiledCol < N) {
            As[ty][tx] = A[row * N + tiledCol];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load B tile
        if (tiledRow < N && col < N) {
            Bs[ty][tx] = B[tiledRow * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute partial dot product with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            sum += As[ty][k] * Bs[k][tx];
            sum += As[ty][k+1] * Bs[k+1][tx];
            sum += As[ty][k+2] * Bs[k+2][tx];
            sum += As[ty][k+3] * Bs[k+3][tx];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check inputs
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions incompatible");

    int N = A.size(0);
    int P = B.size(1);

    auto C = torch::zeros({N, P}, torch::TensorOptions().dtype(A.dtype()).device(A.device()));

    // Set grid and block dimensions
    dim3 threadsPerBlock(TILE_SIZE, TILE_SIZE);
    dim3 numBlocks((P + TILE_SIZE - 1) / TILE_SIZE, 
                   (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<numBlocks, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

